interface Expr { accept(v: ExprOperator): number }
class Num implements Expr {
  constructor(public value: number) {}
  accept(v: ExprOperator) { return v.visitNum(this) }
}
class Add implements Expr {
  constructor(public left: Expr, public right: Expr) {}
  accept(v: ExprOperator) { return v.visitAdd(this) }
}
interface ExprOperator { visitNum(n: Num): number; visitAdd(a: Add): number }

interface Shape { accept(op: ShapeOp): void }
class Circle implements Shape { constructor(public r: number) {} accept(op: ShapeOp) { op.visitCircle(this) } }
class Rect implements Shape { constructor(public w: number, public h: number) {} accept(op: ShapeOp) { op.visitRect(this) } }
interface ShapeOp { visitCircle(c: Circle): void; visitRect(r: Rect): void }
class Render implements ShapeOp { visitCircle(){} visitRect(){} }
class Serialize implements ShapeOp { visitCircle(){} visitRect(){} }

// Version A: operation objects
interface Shape { accept(op: ShapeOp): number }
class Circle implements Shape { constructor(public r:number){} accept(op){ return op.visitCircle(this) } }
class Rect implements Shape { constructor(public w:number, public h:number){} accept(op){ return op.visitRect(this) } }
interface ShapeOp { visitCircle(c:Circle): number; visitRect(r:Rect): number }
class Area implements ShapeOp { visitCircle(c){ return Math.PI*c.r*c.r } visitRect(r){ return r.w*r.h } }

// Version B: centralized type switch
type ShapeTag = { kind: 'circle', r:number } | { kind: 'rect', w:number, h:number }
function area(shape: ShapeTag) {
  switch(shape.kind) {
    case 'circle': return Math.PI*shape.r*shape.r
    case 'rect': return shape.w*shape.h
  }
}
